1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { marked } from 'marked';
4	import { parseFrontmatter, type Frontmatter } from './frontmatter.js';
5	
6	export interface PageMetadata {
7	  slug: string;
8	  title: string;
9	  date?: string;
10	  tags?: string[];
11	  [key: string]: unknown;
12	}
13	
14	export interface Page {
15	  metadata: PageMetadata;
16	  html: string;
17	}
18	
19	function ensureDirectoryExists(dir: string): void {
20	  if (!fs.existsSync(dir)) {
21	    fs.mkdirSync(dir, { recursive: true });
22	  }
23	}
24	
25	function getMarkdownFiles(contentDir: string): string[] {
26	  if (!fs.existsSync(contentDir)) {
27	    return [];
28	  }
29	
30	  const entries = fs.readdirSync(contentDir, { withFileTypes: true });
31	  const files: string[] = [];
32	
33	  for (const entry of entries) {
34	    if (entry.isFile() && entry.name.endsWith('.md')) {
35	      files.push(path.join(contentDir, entry.name));
36	    }
37	  }
38	
39	  return files;
40	}
41	
42	function slugify(filename: string): string {
43	  return filename.replace(/\.md$/, '').toLowerCase().replace(/[^a-z0-9]+/g, '-');
44	}
45	
46	function parseMarkdownFile(filePath: string): Page {
47	  const content = fs.readFileSync(filePath, 'utf-8');
48	  const { data, content: markdown } = parseFrontmatter(content);
49	  const html = marked(markdown);
50	
51	  const filename = path.basename(filePath);
52	  const slug = slugify(filename);
53	
54	  const metadata: PageMetadata = {
55	    slug,
56	    title: (data.title as string) || slug,
57	    ...(data.date && { date: data.date }),
58	    ...(data.tags && { tags: data.tags }),
59	  };
60	
61	  return {
62	    metadata,
63	    html,
64	  };
65	}
66	
67	function renderPageTemplate(page: Page): string {
68	  const { metadata, html } = page;
69	  const dateStr = metadata.date ? `<meta name="date" content="${metadata.date}">` : '';
70	  const tagsStr = metadata.tags
71	    ? `<meta name="tags" content="${(metadata.tags as string[]).join(', ')}">`
72	    : '';
73	
74	  return `<!DOCTYPE html>
75	<html lang="en">
76	<head>
77	  <meta charset="UTF-8">
78	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
79	  <title>${metadata.title}</title>
80	  ${dateStr}
81	  ${tagsStr}
82	</head>
83	<body>
84	  <header>
85	    <a href="/index.html">← Home</a>
86	  </header>
87	  <article>
88	    <h1>${metadata.title}</h1>
89	    ${metadata.date ? `<p class="date">${metadata.date}</p>` : ''}
90	    ${metadata.tags ? `<p class="tags">Tags: ${(metadata.tags as string[]).join(', ')}</p>` : ''}
91	    ${html}
92	  </article>
93	</body>
94	</html>`;
95	}
96	
97	function renderIndexTemplate(pages: Page[]): string {
98	  const pageLinks = pages
99	    .map(
100	      (page) =>
101	        `<li><a href="${page.metadata.slug}.html">${page.metadata.title}</a>${page.metadata.date ? ` (${page.metadata.date})` : ''}</li>`
102	    )
103	    .join('\n');
104	
105	  return `<!DOCTYPE html>
106	<html lang="en">
107	<head>
108	  <meta charset="UTF-8">
109	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
110	  <title>Home</title>
111	</head>
112	<body>
113	  <header>
114	    <h1>Welcome</h1>
115	  </header>
116	  <main>
117	    <ul>
118	      ${pageLinks}
119	    </ul>
120	  </main>
121	</body>
122	</html>`;
123	}
124	
125	export function build(contentDir: string, outputDir: string): void {
126	  ensureDirectoryExists(outputDir);
127	
128	  const markdownFiles = getMarkdownFiles(contentDir);
129	
130	  if (markdownFiles.length === 0) {
131	    fs.writeFileSync(
132	      path.join(outputDir, 'index.html'),
133	      `<!DOCTYPE html>
134	<html lang="en">
135	<head>
136	  <meta charset="UTF-8">
137	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
138	  <title>Home</title>
139	</head>
140	<body>
141	  <h1>Welcome</h1>
142	  <p>No pages found.</p>
143	</body>
144	</html>`
145	    );
146	    return;
147	  }
148	
149	  const pages = markdownFiles.map((file) => parseMarkdownFile(file));
150	
151	  pages.forEach((page) => {
152	    const htmlContent = renderPageTemplate(page);
153	    const outputFile = path.join(outputDir, `${page.metadata.slug}.html`);
154	    fs.writeFileSync(outputFile, htmlContent);
155	  });
156	
157	  const indexHtml = renderIndexTemplate(pages);
158	  fs.writeFileSync(path.join(outputDir, 'index.html'), indexHtml);
159	}
