1	export interface Frontmatter {
2	  title?: string;
3	  date?: string;
4	  tags?: string[];
5	  [key: string]: unknown;
6	}
7	
8	interface ParseResult {
9	  data: Frontmatter;
10	  content: string;
11	}
12	
13	function parseYamlValue(value: string): unknown {
14	  const trimmed = value.trim();
15	
16	  if (trimmed === 'true') return true;
17	  if (trimmed === 'false') return false;
18	  if (trimmed === 'null' || trimmed === '') return null;
19	
20	  const num = Number(trimmed);
21	  if (!isNaN(num) && trimmed !== '') return num;
22	
23	  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
24	    const arrayStr = trimmed.slice(1, -1);
25	    return arrayStr.split(',').map((item) => item.trim());
26	  }
27	
28	  return trimmed;
29	}
30	
31	function parseYamlFrontmatter(yamlContent: string): Frontmatter {
32	  const data: Frontmatter = {};
33	  const lines = yamlContent.split('\n');
34	
35	  for (const line of lines) {
36	    const colonIndex = line.indexOf(':');
37	    if (colonIndex === -1) continue;
38	
39	    const key = line.substring(0, colonIndex).trim();
40	    const value = line.substring(colonIndex + 1).trim();
41	
42	    data[key] = parseYamlValue(value);
43	  }
44	
45	  return data;
46	}
47	
48	export function parseFrontmatter(content: string): ParseResult {
49	  const lines = content.split('\n');
50	
51	  if (lines[0] !== '---') {
52	    return {
53	      data: {},
54	      content,
55	    };
56	  }
57	
58	  let endIndex = -1;
59	  for (let i = 1; i < lines.length; i++) {
60	    if (lines[i] === '---') {
61	      endIndex = i;
62	      break;
63	    }
64	  }
65	
66	  if (endIndex === -1) {
67	    return {
68	      data: {},
69	      content,
70	    };
71	  }
72	
73	  const yamlContent = lines.slice(1, endIndex).join('\n');
74	  const markdownContent = lines.slice(endIndex + 1).join('\n');
75	  const data = parseYamlFrontmatter(yamlContent);
76	
77	  return {
78	    data,
79	    content: markdownContent.trim(),
80	  };
81	}
