1	export interface ParsedArgs {
2	  command: string | null;
3	  contentDir: string;
4	  outputDir: string;
5	  help: boolean;
6	}
7	
8	export function parseArgs(argv: string[]): ParsedArgs {
9	  const result: ParsedArgs = {
10	    command: argv[0] || null,
11	    contentDir: './content',
12	    outputDir: './dist',
13	    help: false,
14	  };
15	
16	  for (let i = 1; i < argv.length; i++) {
17	    const arg = argv[i];
18	
19	    if (arg === '--help') {
20	      result.help = true;
21	    } else if (arg === '--content' && i + 1 < argv.length) {
22	      result.contentDir = argv[++i];
23	    } else if (arg === '--output' && i + 1 < argv.length) {
24	      result.outputDir = argv[++i];
25	    }
26	  }
27	
28	  return result;
29	}
